    "venue": "IEEE Symposium on Security and Privacy (S&P)"
  },
  "brief": {
    "title": "Bot Mitigation at Scale: How Modern Web Security Services Protect Scientific Publishing Platforms",
    "one_liner": "An analysis of how challenge-based bot verification systems safeguard high-value academic web properties against automated threats.",
    "goal": "The viewer should understand the scale of bot traffic threatening academic publishers, the mechanisms used by CDN-based security services to mitigate these threats, and the measurable impact on platform availability and integrity."
  },
  "sections": [
    {
      "id": "threat-landscape",
      "title": "The Bot Threat Landscape for Academic Publishers",
      "objective": "Present the scale and nature of malicious bot traffic targeting scientific content platforms."
    },
    {
      "id": "verification-mechanism",
      "title": "Challenge-Based Verification Pipeline",
      "objective": "Explain the multi-stage verification workflow from initial request interception to successful access grant."
    },
    {
      "id": "performance-metrics",
      "title": "Performance and Security Outcomes",
      "objective": "Show quantitative results of deploying CDN-level bot mitigation on a major science publisher."
    },
    {
      "id": "tradeoffs",
      "title": "Usability vs. Security Trade-offs",
      "objective": "Discuss the balance between blocking bots and maintaining seamless access for legitimate researchers."
    }
  ],
  "metrics": [
    {
      "label": "Estimated share of internet traffic from bots",
      "value": "~47%"
    },
    {
      "label": "Malicious bot share of total bot traffic",
      "value": "30%"
    },
    {
      "label": "Average verification latency for legitimate users",
      "value": "<2 seconds"
    },
    {
      "label": "Reduction in scraping attempts after deployment",
      "value": "85%"
    },
    {
      "label": "Uptime maintained under DDoS-level bot surges",
      "value": "99.97%"
    }
  ]
}

