  pipeline: `infographic sequence-interaction-default-badge-card
data
  title Challenge-Based Verification Pipeline
  desc Five-stage CDN-edge verification flow — total latency &lt;2 seconds for legitimate human users
  sequences
    - label Client
      children
        - label HTTP Request
          id c-req
          step 0
          icon globe line
        - label Execute Challenge
          id c-challenge
          step 2
          icon code line
        - label Submit Response
          id c-resp
          step 3
          icon arrow right line
        - label Access Content
          id c-access
          step 4
          icon check line
    - label CDN Edge Node
      children
        - label 1. Request Interception
          id e-intercept
          step 0
          desc &lt;50 ms
          icon shield line
        - label 2. Threat Scoring
          id e-score
          step 1
          desc ~100 ms
          icon chart bar line
        - label 3. Challenge Issuance
          id e-issue
          step 2
          desc ~500 ms
          icon key line
        - label 4. Verification Check
          id e-verify
          step 3
          desc ~200 ms
          icon check shield
        - label 5. Access Grant
          id e-grant
          step 4
          desc &lt;50 ms
          icon unlock line
  relations
    c-req - Intercepted by CDN edge -> e-intercept
    e-intercept - Evaluate risk signals -> e-score
    e-score - Risk exceeds threshold -> e-issue
    e-issue - JS/CAPTCHA challenge served -> c-challenge
    c-challenge - Submit challenge response -> c-resp
    c-resp - Validate and assign Ray ID -> e-verify
    e-verify - Forward with session token -> e-grant
    e-grant - Content delivered to origin -> c-access
theme
  palette #06b6d4 #0ea5e9 #3b82f6 #6366f1 #8b5cf6`,

  beforeafter: `infographic compare-binary-horizontal-badge-card-arrow
data
  title Measured Impact: Before vs. After Mitigation
  desc Key metrics before and after CDN-based bot mitigation deployment
  compares
    - label Before Mitigation
      children
        - label Daily Scraping
          value 1.2
