        - label Origin CPU Load
          value 78
          desc Percent average
          icon server line
        - label User Complaints
          value 1200
          desc Per month
          icon message line
        - label Surge Uptime
          value 98.5
          desc Percent
          icon activity line
    - label After Mitigation
      children
        - label Daily Scraping
          value 0.18
          desc Million attempts
          icon download line
        - label Origin CPU Load
          value 42
          desc Percent average
          icon server line
        - label User Complaints
          value 340
          desc Per month
          icon message line
        - label Surge Uptime
          value 99.97
          desc Percent
          icon activity line
theme
  palette #64748b #10b981`,

