      desc University IP ranges and known research networks can be allowlisted to reduce unnecessary challenges
      icon building
    - label Transparency
      desc Clear messaging informs users about verification delays and security processes
      icon eye line
    - label Privacy
      desc Threat detection is balanced with user privacy; data handling practices are clearly disclosed
      icon lock line
theme
  palette #06b6d4 #0ea5e9 #3b82f6 #6366f1`

};

const containers = {
  threat:     { id: 'threat-container',     syntax: 'threat' },
  pipeline:   { id: 'pipeline-container',   syntax: 'pipeline' },
  beforeafter:{ id: 'beforeafter-container',syntax: 'beforeafter' },
  tradeoffs:  { id: 'tradeoffs-container',  syntax: 'tradeoffs' }
};

const instances = {};

function renderAll() {
  Object.entries(containers).forEach(([key, cfg]) => {
    const el = document.getElementById(cfg.id);
    if (!el) return;
    const inst = new AntVInfographic.Infographic({
      container: `#${cfg.id}`,
      width: el.parentElement.clientWidth - 56,
      height: cfg.id === 'pipeline-container' ? 520 : cfg.id === 'beforeafter-container' ? 420 : 320,
    });
    inst.render(syntaxes[cfg.syntax].trim());
    instances[key] = inst;
  });
}

document.fonts?.ready.then(() => {
  Object.values(instances).forEach(i => i.render(syntaxes[Object.keys(instances).find(k => instances[k] === i)].trim()));
}).catch(() => {});

renderAll();
</script>
