const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 1600, height: 1200 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for AntVInfographic to be available
  await page.waitForFunction(() => typeof window.AntVInfographic !== 'undefined', { timeout: 10000 });

  // Wait for all infographic containers to be populated
  await page.waitForTimeout(3000);

  // Wait for SVG elements to appear inside containers (indicates rendering complete)
  await page.waitForFunction(() => {
    const containers = ['threat-container', 'pipeline-container', 'beforeafter-container', 'tradeoffs-container'];
    return containers.every(id => {
      const el = document.getElementById(id);
      return el && el.querySelector('svg');
    });
  }, { timeout: 15000 }).catch(() => console.log('Some containers may not have SVGs, proceeding...'));

  // Extra time for animations and fonts
  await page.waitForTimeout(2000);

  // Take full-page screenshot at 2x for high quality
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    deviceScaleFactor: 2,
    type: 'png'
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})().catch(err => {
  console.error('Error:', err.message);
  process.exit(1);
});

