const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1600, height: 1200 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForFunction(() => typeof window.AntVInfographic !== 'undefined', { timeout: 10000 });
  await page.waitForTimeout(4000);

  const results = await page.evaluate(() => {
    const ids = ['threat-container', 'pipeline-container', 'beforeafter-container', 'tradeoffs-container'];
    return ids.map(id => {
      const el = document.getElementById(id);
      if (!el) return { id, status: 'MISSING' };
      const svg = el.querySelector('svg');
      const canvas = el.querySelector('canvas');
      const hasContent = el.children.length > 0;
      const svgSize = svg ? svg.getAttribute('width') + 'x' + svg.getAttribute('height') : 'no-svg';
      return { id, status: hasContent ? 'RENDERED' : 'EMPTY', type: svg ? 'SVG' : (canvas ? 'CANVAS' : 'UNKNOWN'), svgSize, childCount: el.children.length };
    });
  });
  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})().catch(e => console.error(e.message));
