      const svg = el?.querySelector('svg');
      if (!svg) return { id, svg: 'none' };
      // Get all text content recursively
      const walker = document.createTreeWalker(svg, NodeFilter.SHOW_TEXT);
      const texts = [];
      let node;
      while (node = walker.nextNode()) {
