      // Get SVG inner HTML snippet (first 500 chars)
      const inner = svg.innerHTML.substring(0, 600);
      return { id, textCount: texts.length, sampleTexts: texts.slice(0, 12), innerPreview: inner };
    });
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})().catch(e => console.error(e.message));
