const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1600, height: 1200 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForFunction(() => typeof window.AntVInfographic !== 'undefined');
  await page.waitForTimeout(4000);

  const info = await page.evaluate(() => {
    const containers = {
      threat: 'threat-container',
      pipeline: 'pipeline-container',
      impact: 'beforeafter-container',
      tradeoffs: 'tradeoffs-container'
    };
    const results = {};
    for (const [key, id] of Object.entries(containers)) {
      const svg = document.getElementById(id)?.querySelector('svg');
      if (!svg) { results[key] = 'no svg'; continue; }
      const walker = document.createTreeWalker(svg, NodeFilter.SHOW_TEXT);
      const texts = [];
      let node;
      while (node = walker.nextNode()) {
        const t = node.textContent.trim();
        if (t && t.length > 1) texts.push(t);
      }
      results[key] = { count: texts.length, texts };
    }
    return results;
  });
  console.log(JSON.stringify(info, null, 1));
  await browser.close();
})().catch(e => console.error(e.message));
